  "implementation": "def solve(case):
    nodes = case['nodes']
    core_dist = case['core_distance']
    distances = case['distances']

    # Build edges with mutual reachability
    edges = []
    for u, v, d in distances:
        w = max(core_dist[u], core_dist[v], d)
        if u > v:
            u, v = v, u
        edges.append((u, v, w))

    # Sort: primary by weight, secondary by u, tertiary by v
    edges.sort(key=lambda e: (e[2], e[0], e[1]))

    # Union-Find with path compression and union by rank
    parent = {n: n for n in nodes}
    rank = {n: 0 for n in nodes}

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True

    mst_edges = []
    total_weight = 0.0
    n = len(nodes)

    for u, v, w in edges:
        if union(u, v):
            mst_edges.append([u, v, w])
            total_weight += w
            if len(mst_edges) == n - 1:
                break

    if len(mst_edges) != n - 1:
        raise ValueError('Graph is disconnected, cannot form MST')

    return {
        'mst_edges': mst_edges,
        'total_weight': total_weight
    }
